import{_ as i,l as o,o as e,c as l,v as t,p as n,x as s,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"匿名页对文件页","description":"","frontmatter":{"title":"匿名页对文件页","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/anon-vs-file-page.md","filePath":"cs/anon-vs-file-page.md","lastUpdated":1789023840000}'),h={name:"cs/anon-vs-file-page.md"};function m(f,a,B,E,_,u){const r=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="匿名页对文件页" tabindex="-1">匿名页对文件页 <a class="header-anchor" href="#匿名页对文件页" aria-label="Permalink to &quot;匿名页对文件页&quot;">​</a></h1><div class="epigraph"><p>文件页扔掉还能从文件再读；匿名页没有文件副本，脏了就必须进交换区，否则内容消失。</p><footer>—— 据 Silberschatz et al.；Bovet and Cesati 对 Linux 页来源的整理</footer></div><p><a href="/cs/thrashing">上一课</a>把所有页算进工作集。<a href="/cs/page-fault-path">缺页路径</a>已经能从文件填页或填零。<a href="/cs/page-replace">置换</a>说只读文本可丢弃。缺口是钉死两类<strong>后备</strong>：文件页（inode + 偏移）与匿名页（堆、栈、匿名 mmap、COW 私有副本）。CLOCK 扫描到它们时，写回目标不是同一个设备。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若把文本页写进 swap，浪费交换槽且与可执行文件重复。若把改过的堆页只标无效而不写出，进程稍后读到的是空洞或别人的帧。缺口不是再讲 VMA，而是页描述符上的来源：文件映射指向 <a href="/cs/vfs">VFS</a> 之后才完全展开的 inode；匿名页指向交换槽或「尚无槽的脏匿名」。干净文件页：解映射即可。脏文件页：写回文件。脏匿名页：写 swap。</p><p>本课不把 shmem/tmpfs 的全部特例写完，只承认它们像「有文件外形的匿名」。</p><p><span class="marginnote">同一物理页可被文件映射共享。淘汰时要看映射类型与脏位，不能只看 CLOCK 指针。后课 mmap 会把共享/私有写清楚；本课先分后备设备。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>缺页填页时记录 mapping。置换选中：查来源。文件且干净 → 丢；文件且脏 → 加入对文件系统的回写（缓冲课）。匿名且干净（如未写过的零页）→ 丢；匿名且脏 → 分配交换槽、写交换设备。之后 PTE 改为「不在内存」，编码里带槽号或再缺页时查换出表。</p>',9)),(e(),n(c,null,{default:s(()=>[d(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20VIC%5B%22%E7%89%BA%E7%89%B2%E9%A1%B5%22%5D%20--%3E%20F%7B%22%E6%96%87%E4%BB%B6%3F%22%7D%0A%20%20F%20--%3E%7C%E5%B9%B2%E5%87%80%7C%20DROP%5B%22%E4%B8%A2%2C%20%E5%86%8D%E8%AF%BB%E6%96%87%E4%BB%B6%22%5D%0A%20%20F%20--%3E%7C%E8%84%8F%7C%20FB%5B%22%E5%86%99%E5%9B%9E%E6%96%87%E4%BB%B6%22%5D%0A%20%20VIC%20--%3E%20A%5B%22%E5%8C%BF%E5%90%8D%E8%84%8F%22%5D%0A%20%20A%20--%3E%20SW%5B%22%E5%86%99%20swap%20%E6%A7%BD%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分类让抖动对策更细：优先丢干净文件页，等于用磁盘文件当免费后备；匿名压力才真正吃 swap。工作集里的堆页因此「更贵」。不要在此展开 ext4 布局；文件只是可再次 <code>readpage</code> 的对象。<a href="/cs/paging-vm">分页</a> 仍然只看见有效位；来源在内核页框数据结构里。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入交换分区的条带与优先级全文。不把设备页（framebuffer）混进匿名。文件空洞与稀疏文件在缺页时可能填零，仍算文件来源。下一课才问 swap 设备长什么样、槽如何分配。</p><p>后课默认：匿名脏页必须有交换去处。槽在哪、如何成设备，下一课 swap。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>文件页以文件为后备；匿名脏页以 swap 为后备。</li><li>淘汰代价不同，工作集会计应分开看。</li><li>交换槽与设备是下一课。</li><li>出处：Silberschatz et al., <em>OSC</em>；Bovet and Cesati, <em>ULK</em>；Tanenbaum <em>MOS</em>。</li></ul>',7))])}const g=i(h,[["render",m]]);export{A as __pageData,g as default};
